"""Local file adapters: blob storage outside the web root (05/SG6) and the upload log."""

from __future__ import annotations

import os
from datetime import datetime
from pathlib import Path
from uuid import UUID

import anyio
from sqlalchemy import insert
from sqlalchemy.ext.asyncio import AsyncConnection

from .schema import uploads


class LocalBlobStore:
    """Owner-only permissions; names are generated by the server, never taken from the client."""

    def __init__(self, root: Path) -> None:
        self.root = root

    def _write(self, name: str, data: bytes) -> None:
        if "/" in name or name.startswith("."):
            raise ValueError("stored names are flat, server-generated identifiers")
        self.root.mkdir(mode=0o700, parents=True, exist_ok=True)
        path = self.root / name
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(fd, "wb") as f:
            f.write(data)

    async def put(self, name: str, data: bytes) -> None:
        await anyio.to_thread.run_sync(self._write, name, data)


class PgUploadLog:
    def __init__(self, conn: AsyncConnection) -> None:
        self.conn = conn

    async def add(
        self,
        upload_id: UUID,
        tenant_id: UUID,
        stored_name: str,
        media_type: str,
        size_bytes: int,
        created_by: str,
        created_at: datetime,
    ) -> None:
        await self.conn.execute(
            insert(uploads).values(
                id=upload_id,
                tenant_id=tenant_id,
                stored_name=stored_name,
                media_type=media_type,
                size_bytes=size_bytes,
                created_by=created_by,
                created_at=created_at,
            )
        )
